/**
 * What counts as noise in a daily workspace record.
 *
 * A daily diff is only useful if it shows work. Build outputs, caches, editor
 * swap files, OS metadata and the owner's own gitignored paths are changes the
 * tools made, not the owner. The filter is shared by the content capture, the
 * FSEvents recorder and the digest's mtime fallback so all three agree.
 *
 * The list is deliberately conservative: a directory or suffix is excluded only
 * when its content is generated by a tool. Anything ambiguous stays. A file the
 * filter hides can still be found on disk, and every capture reports how many
 * paths it skipped.
 *
 * 每日工作记录里什么算噪声。
 *
 * 每日 diff 只有展示"工作"才有用。构建产物、缓存、编辑器交换文件、系统元数据与所有者
 * 自己 gitignore 的路径，是工具改的，不是所有者。内容采集、FSEvents 记录器与摘要的
 * mtime 回退共用这份过滤，三者因此一致。
 *
 * 列表刻意保守：只有内容确实由工具生成的目录或后缀才排除，模棱两可的一律保留。被过滤器
 * 藏起的文件仍在磁盘上，而且每次采集都会报告跳过了多少路径。
 */
import { execFile } from "node:child_process";
import { basename, resolve } from "node:path";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

/** Directory names whose contents are tool output, never the owner's work. 内容是工具产物而非所有者工作的目录名。 */
export const NOISE_DIRECTORIES = new Set([
  ".git",
  ".clone",
  ".clone-ai",
  ".idea",
  ".next",
  ".nuxt",
  ".output",
  ".parcel-cache",
  ".svelte-kit",
  ".turbo",
  ".vercel",
  ".cache",
  ".gradle",
  ".ivy2",
  ".m2",
  ".pnpm-store",
  ".yarn",
  ".pytest_cache",
  ".mypy_cache",
  ".ruff_cache",
  ".tox",
  "__pycache__",
  "node_modules",
  "bower_components",
  "jspm_packages",
  "dist",
  "build",
  "out",
  "target",
  "coverage",
  "DerivedData",
  "Pods",
  "Carthage",
  "TestResults",
  "venv",
  ".venv",
  "tmp",
  "temp",
]);

/** Basenames that are OS/editor/tool metadata at any depth. 任意深度的系统/编辑器/工具元数据文件名。 */
const NOISE_BASENAMES = new Set([
  ".DS_Store",
  ".localized",
  "Thumbs.db",
  "desktop.ini",
  ".eslintcache",
  ".stylelintcache",
  "npm-debug.log",
  "yarn-error.log",
  ".coverage",
]);

/** Suffixes whose content is generated. 内容由工具生成的扩展名。 */
const NOISE_SUFFIXES = new Set([
  ".swp",
  ".swo",
  ".tmp",
  ".temp",
  ".part",
  ".crdownload",
  ".download",
  ".pyc",
  ".pyo",
  ".class",
  ".o",
  ".obj",
  ".a",
  ".so",
  ".dylib",
  ".dll",
  ".exe",
  ".pdb",
  ".ilk",
  ".tsbuildinfo",
  ".log",
  ".map",
  ".pid",
  ".seed",
  ".stackdump",
  ".orig",
  ".rej",
  ".min.js",
  ".min.css",
]);

/** Hidden directory segments are tooling; hidden *files* (`.env`, `.gitignore`) are work. 隐藏目录段是工具；隐藏文件仍是工作。 */
export function isNoiseDirectoryName(name: string): boolean {
  return name.startsWith(".") || NOISE_DIRECTORIES.has(name);
}

/** True for a file path that no daily diff should list. 每日 diff 不应列出的文件路径。 */
export function isNoiseFile(path: string): boolean {
  const name = basename(path);
  if (NOISE_BASENAMES.has(name)) return true;
  if (name.startsWith(".#") || (name.startsWith("#") && name.endsWith("#")) || name.endsWith("~")) return true;
  const lower = name.toLowerCase();
  for (const suffix of NOISE_SUFFIXES) {
    if (lower.endsWith(suffix)) return true;
  }
  return false;
}

/**
 * True when any directory segment between `root` and `path` is noise, or the
 * file itself is noise. A path outside the root is noise by construction.
 * 当 `root` 与 `path` 之间的任一目录段是噪声、或文件本身是噪声时为真。根之外的路径
 * 按构造也算噪声。
 */
export function isNoisePath(path: string, root: string): boolean {
  const relative = path.startsWith(`${root}/`) ? path.slice(root.length + 1) : undefined;
  if (relative === undefined) return true;
  const parts = relative.split("/");
  if (parts.some((part) => part.length === 0)) return true;
  if (parts.slice(0, -1).some(isNoiseDirectoryName)) return true;
  return isNoiseFile(path);
}

export interface GitIgnoreIndex {
  matches(path: string): boolean;
  sources: number;
}

const EMPTY_INDEX: GitIgnoreIndex = { matches: () => false, sources: 0 };

/**
 * The owner's own definition of generated output, for the untracked files git
 * ignores. Tracked files are never ignored, so editing them still shows up.
 * 所有者自己对"生成物"的定义，覆盖 git 忽略的未跟踪文件。已跟踪文件不会被忽略，
 * 因此对它们的修改仍会出现。
 */
export async function loadGitIgnoreIndex(repositories: readonly string[]): Promise<GitIgnoreIndex> {
  if (repositories.length === 0) return EMPTY_INDEX;
  const files = new Set<string>();
  const directories: string[] = [];
  let sources = 0;
  for (const repository of repositories.slice(0, 20)) {
    try {
      const { stdout } = await execFileAsync(
        "git",
        [
          "-C", repository,
          "--no-pager",
          "--no-optional-locks",
          "-c", "core.fsmonitor=false",
          "ls-files", "-z", "--others", "--ignored", "--exclude-standard", "--directory",
        ],
        { timeout: 4_000, maxBuffer: 8 * 1024 * 1024 },
      );
      sources += 1;
      for (const entry of stdout.split("\0")) {
        if (entry.length === 0) continue;
        if (entry.endsWith("/")) {
          directories.push(`${resolve(repository, entry)}/`);
        } else {
          files.add(resolve(repository, entry));
        }
      }
    } catch {
      // A non-repository, a missing git, or a huge ignored tree: the other
      // filters still apply, and the capture reports what it skipped.
      // 非仓库、缺少 git、或过大的忽略树：其他过滤仍然生效，采集会报告跳过了什么。
    }
  }
  return {
    sources,
    matches(path: string): boolean {
      if (files.has(path)) return true;
      return directories.some((directory) => path === directory.slice(0, -1) || path.startsWith(directory));
    },
  };
}

interface CachedIndex {
  at: number;
  index: Promise<GitIgnoreIndex>;
}

const cache = new Map<string, CachedIndex>();
const CACHE_TTL_MS = 5 * 60_000;

/** Cached per repository set; a `.gitignore` edit invalidates by calling `resetNoiseCache`. 按仓库集合缓存；`.gitignore` 变更通过 `resetNoiseCache` 失效。 */
export function cachedGitIgnoreIndex(repositories: readonly string[], now: number = Date.now()): Promise<GitIgnoreIndex> {
  const key = [...new Set(repositories)].sort().join("\0");
  if (key.length === 0) return Promise.resolve(EMPTY_INDEX);
  const cached = cache.get(key);
  if (cached !== undefined && now - cached.at < CACHE_TTL_MS) return cached.index;
  const index = loadGitIgnoreIndex(repositories);
  cache.set(key, { at: now, index });
  return index;
}

export function resetNoiseCache(): void {
  cache.clear();
}
